{
  "technical_and_design_decisions": [
    "Assume existing Spring XD codebase with message bus abstraction (RabbitMQ, Kafka, etc.) and stream deployment management via ZooKeeper/config store.",
    "Message bus resource cleanup (U1, U2) will extend the message bus interface with a `cleanupResources(stream)` method, implemented for each supported binder.",
    "Stream deployment property editing (U3) will introduce a new REST/shell command to update properties and trigger a rolling module restart without stream destruction.",
    "Deployment manifest from file (U4) will support YAML/JSON parsing and merging with inline properties, reusing existing property resolution logic.",
    "Optional trace (U6) will leverage Spring Integration's global wiretap/channel interceptor mechanism, activated via deployment properties with wildcard support.",
    "Side channels (U7) will be implemented by extending the module deployment manifest schema to include additional channel definitions, which are created as tap channels within the module's integration flow.",
    "Reference architectures (U5) and taxi trip sample (U8) are delivered as documentation and sample applications, not core framework changes."
  ],
  "assumptions": [
    "Development team has deep familiarity with Spring XD internals, Spring Integration, and the supported message bus binders.",
    "The message bus abstraction already provides necessary hooks for resource lifecycle management; we only need to implement cleanup logic per binder.",
    "Stream deployment properties are stored in a centralized config store (e.g., ZooKeeper) and can be updated atomically.",
    "Rolling module restart for property edits is feasible without full stream redeployment.",
    "Wildcard module selection for trace can be resolved at deployment time by matching module names.",
    "Side channels are created as additional Spring Integration channels wired to the message bus as tap channels, not affecting primary input/output.",
    "The DEBS 2015 taxi trip dataset is available and can be simulated for the sample application.",
    "Effort estimates are for a single senior developer working full-time; no parallelization or team overhead considered.",
    "Testing includes unit, integration, and end-to-end tests for each feature, using existing test infrastructure.",
    "Documentation updates cover user guide, shell command reference, and sample READMEs."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Message Bus Resource Cleanup",
      "activity_description": "Extend message bus interface with cleanupResources(stream) and implement for RabbitMQ, Kafka, and other supported binders. Integrate with stream destruction lifecycle to automatically delete associated queues/topics. Include handling of stale resources (U1, U2).",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A2",
      "activity_name": "Stream Deployment Property Editing",
      "activity_description": "Add REST endpoint and shell command to update deployment properties of an existing stream (deployed or undeployed). Implement rolling module restart to apply changes without stream destruction. Update property resolution and validation (U3).",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A3",
      "activity_name": "Deployment Manifest from File",
      "activity_description": "Implement file-based deployment property input (YAML/JSON). Add parsing, merging with inline properties, and validation. Extend shell and REST commands to accept file path or content (U4).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A4",
      "activity_name": "Optional Trace for Stream Modules",
      "activity_description": "Add deployment property support for module tracing (module.<name>.trace, module.*.trace). Integrate with Spring Integration wiretap/channel interceptor to enable logging/notifications per module. Implement wildcard resolution at deployment time (U6).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A5",
      "activity_name": "Optional Side Channels for Modules",
      "activity_description": "Extend module deployment manifest schema to allow arbitrary side channel definitions. Modify module deployment to create additional tap channels within the flow and bind them to the message bus. Ensure side channels can be used for tracing/tracking (U7).",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A6",
      "activity_name": "Reference Architecture Documentation and Samples",
      "activity_description": "Create reference architecture documents for common Spring XD use cases. Provide sample stream definitions, deployment manifests, and configuration guidelines as a starting point for POCs (U5).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A7",
      "activity_name": "Taxi Trip Analytics Sample Application",
      "activity_description": "Develop a complete Spring XD stream application for the DEBS 2015 Grand Challenge: ingest NYC taxi trip data, process events, perform real-time analytics. Include custom modules, deployment manifests, and documentation (U8).",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A8",
      "activity_name": "Testing and Integration",
      "activity_description": "Write unit tests for new APIs and binder implementations. Develop integration tests for stream lifecycle with cleanup, property editing, tracing, and side channels. Perform end-to-end testing of sample applications.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A9",
      "activity_name": "Documentation Updates",
      "activity_description": "Update user guide with new features: resource cleanup, property editing, manifest file, trace, side channels. Update shell command reference and REST API documentation.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A10",
      "activity_name": "Code Review, Refactoring, and Bug Fixes",
      "activity_description": "Conduct code reviews for all changes. Refactor any duplicated or complex code. Address bugs found during testing and integration.",
      "most_likely_effort": 24
    }
  ],
  "reported_total": {
    "most_likely_effort": 288
  }
}

